Definition hi_heap0 (LB : list (Z * Z)) (cr : credit) (M : word -> option byte) (VM : VmMaps) : Prop :=
  exists (RUNp : RunP) (s : PState) (L : mled) (LBb : list block),
       alloc_ceiling = sptop - 2 ^ 23                   (* [comment removed for export] *)
    /\ LB = map blk_iv LBb
    /\ RHEAP s LBb M                                    (* [comment removed for export] *)
    /\ creach (ps_m s) L                                (* [comment removed for export] *)
    /\ Permutation (ld_live L) (map blk_slot LBb)       (* [comment removed for export] *)
    /\ KL2 RESV IMG_HI L (ps_brk s) VM                  (* [comment removed for export] *)
    /\ mem_inv rsegs M                                  (* [comment removed for export] *)
    /\ rauxv_ok M sptop                                 (* [comment removed for export] *)
    /\ (forall a : word, RCTX + 928 <= bv_unsigned a < RCTX + 936 -> M a = None)   (* [comment removed for export] *)
    /\ Forall (fun b => 0 < blk_size b /\ forall i, 0 <= i < blk_size b -> M (wa (blk_addr b + i)) <> None) LBb
    (* [comment removed for export] *)
    /\ RES (ps_m s) (SZ_of LBb) K0                       (* [comment removed for export] *)
    /\ 0 <= fst cr /\ 0 <= snd cr
    /\ Z.of_nat (length LBb) + fst cr <= K0
    /\ (bm_on = true \/ charge LBb + snd cr <= B0)
    /\ live_bytes (vm_maps VM) <= Phi (ps_m s)          (* [comment removed for export] *)
    /\ Z.of_nat (length (vm_reserved VM ++ vm_maps VM)) <= NSEG + Psi (ps_m s)
    /\ Forall (fun p => bv_unsigned (snd p) <= NMAX) (vm_reserved VM ++ vm_maps VM)
    /\ (bm_on = true \/ 2 ^ 39 <= vm_limit VM)    (* [comment removed for export] *)
    /\ vm_limit VM = lim                              (* [comment removed for export] *)
    /\ Forall (fun b => fits lim (blk_size b)) LBb.   (* [comment removed for export] *)
Definition HI0 : heap_iface := {| hi_heap := hi_heap0 |}.

